mapper.select:
SELECT d.id, d.resource_type_id, d.resource_type_name, d.parent_id, d.parent_name, d.order_num, d.`status`, d.delete_flag, d.creator, d.create_time, d.modifier, d.update_time, d.tenant_id, s.tenant_name, d.remark, d.icon, d.approve, d.industry_code, d.app_ver_code, d.resource_property, a.AREA_NAME as province_name, b.AREA_NAME as city_name FROM resource_type d LEFT JOIN sys_tenant_info s ON d.tenant_id = s.tenant_id LEFT JOIN sys_area a on a.AREA_CODE=s.province_id LEFT JOIN sys_area b on b.AREA_CODE=s.city_id WHERE d.delete_flag = 0
AND d.parent_id = #{parentId}
AND d.resource_type_name like CONCAT('%',#{resourceTypeName},'%')
AND d.status = #{status}
AND d.approve = #{approve}
AND d.tenant_id = #{tenantId}
AND d.industry_code = #{industryCode}
AND d.app_ver_code = #{appVerCode}
AND s.tenant_name like CONCAT(CONCAT('%',#{tenantName}),'%')
AND d.resource_property = #{resourceProperty}
order by d.update_time desc

select
    count(1)
from
    resource_type
where
    parent_id = #{resourceTypeId}
    and delete_flag = 0

      and tenant_id = #{tenantId,jdbcType=VARCHAR}


      and industry_code = #{industryCode,jdbcType=VARCHAR}

select
    count(1)
from
    resource_type
where
    resource_type_name = #{resourceTypeName}
    and delete_flag = 0

      and tenant_id = #{tenantId,jdbcType=VARCHAR}


      and resource_type_id != #{resourceTypeId,jdbcType=VARCHAR}


      and industry_code = #{industryCode}


      and app_ver_code = #{appVerCode}

select
    count(1)
from
    resource_conf
where
    delete_flag = 0

      and tenant_id = #{tenantId,jdbcType=VARCHAR}


      and resource_type_id = #{resourceTypeId,jdbcType=VARCHAR}


      and industry_code = #{industryCode}

SELECT d.resource_type_name, d.order_num, d.remark, d.icon, d.approve, d.app_ver_code d.industry_code, d.creator, d.create_time, d.modifier, d.update_time, d.delete_flag FROM resource_type_int d
AND d.app_ver_code IN
#{labelIdItem}

SELECT d.id, d.resource_type_id, d.resource_type_name, d.parent_id, d.parent_name, d.order_num, d.`status`, d.delete_flag, d.creator, d.create_time, d.modifier, d.update_time, d.tenant_id, s.tenant_name, d.remark, d.icon, d.approve, d.industry_code, d.app_ver_code, d.resource_property, a.AREA_NAME as province_name, b.AREA_NAME as city_name FROM resource_type d LEFT JOIN sys_tenant_info s ON d.tenant_id = s.tenant_id LEFT JOIN sys_area a on a.AREA_CODE=s.province_id LEFT JOIN sys_area b on b.AREA_CODE=s.city_id WHERE d.delete_flag = 0 AND d.status = '0'
AND d.parent_id IN
#{labelIdItem}
AND d.parent_id = '0'
AND d.resource_type_id IN
#{labelIdItem}
AND d.tenant_id = #{tenantId}
AND d.industry_code = #{industryCode}
AND d.app_ver_code = #{appVerCode}
AND d.resource_property = #{resourceProperty}
order by d.create_time
desc
order by d.update_time
desc
order by d.create_time desc

SELECT
  resource_type_id,
  parent_id
FROM resource_type WHERE delete_flag = 0 AND status = '0'

  AND resource_type_name like CONCAT('%',#{resourceTypeName},'%')


  AND approve = #{approve}


  AND tenant_id = #{tenantId}


  AND industry_code = #{industryCode}


  AND resource_property = #{resourceProperty}


  AND app_ver_code = #{appVerCode}

SELECT d.id, d.resource_type_id, d.resource_type_name, d.parent_id, d.parent_name, d.order_num, d.`status`, d.delete_flag, d.creator, d.create_time, d.modifier, d.update_time, d.tenant_id, s.tenant_name, d.remark, d.icon, d.approve, d.industry_code, d.app_ver_code, a.AREA_NAME as province_name, b.AREA_NAME as city_name FROM resource_type d LEFT JOIN sys_tenant_info s ON d.tenant_id = s.tenant_id LEFT JOIN sys_area a on a.AREA_CODE=s.province_id LEFT JOIN sys_area b on b.AREA_CODE=s.city_id WHERE d.delete_flag = 0
AND d.resource_type_id = #{resourceTypeId}
AND d.tenant_id = #{tenantId}

SELECT d.id, d.resource_type_id, d.resource_type_name, d.parent_id, d.parent_name, d.order_num, d.`status`, d.delete_flag, d.creator, d.create_time, d.modifier, d.update_time, d.tenant_id, s.tenant_name, d.remark, d.icon, d.approve, d.industry_code, d.app_ver_code, d.resource_property, a.AREA_NAME as province_name, b.AREA_NAME as city_name FROM resource_type d LEFT JOIN sys_tenant_info s ON d.tenant_id = s.tenant_id LEFT JOIN sys_area a on a.AREA_CODE=s.province_id LEFT JOIN sys_area b on b.AREA_CODE=s.city_id WHERE d.delete_flag = 0 AND d.parent_id in
#{labelIdItem.resourceTypeId}
AND d.tenant_id = #{tenantId}
AND d.industry_code = #{industryCode}
AND d.app_ver_code = #{appVerCode}
AND d.resource_property = #{resourceProperty}
order by d.create_time desc
